    public function getUnoAvanzado(Request $request): ?Configuracion {
        return $this->modelo::select('id', 'modelo', 'nombre', 'descripcion', 'llave', 'valor')
            ->when($request->filled('llave'), fn($consulta) => $consulta->where('llave', $request->llave))
            ->first();
    }
}
