class ConfiguracionModeloRepository extends BaseRepository {
    public function obtenerUnoPorModeloYConfiguracion(string $modelo, int $modelo_id, int $configuracion_id): ?ConfiguracionModelo {
        return $this->modelo::select('id', 'model_type', 'modelo_id', 'configuracion_id', 'valor')
            ->with('configuracion:id,nombre,descripcion,llave,tipo')
            ->where(['model_type' => $modelo, 'modelo_id' => $modelo_id, 'configuracion_id' => $configuracion_id])
            ->first();
    }

    public function obtenerTodasPorModelo(Model $modelo): Collection {
        return $this->modelo::select('id', 'model_type', 'modelo_id', 'configuracion_id', 'valor')
            ->with('configuracion:id,modelo,nombre,descripcion,llave,valor,tipo')
            ->where([['model_type', '=', get_class($modelo)], ['modelo_id', '=', $modelo->id]])
            ->get();
    }

    public function eliminarAvanzado(Request $request, ?bool $definitivamente = false): void {
        $configuraciones_modelos = $this->modelo::select('id')
            ->when($request->filled('model_type'), fn($consulta) => $consulta->where('model_type', $request->model_type))
            ->when($request->filled('modelo_id'), fn($consulta) => $consulta->where('modelo_id', $request->modelo_id));

        if ($definitivamente) {
            $configuraciones_modelos->withTrashed()->forceDelete();
        } else {
            $configuraciones_modelos->delete();
        }
    }
}
