class EmpresaUsuarioRepository extends BaseRepository 
    implements ObtenerUnoAvanzado, ActualizarUnoAvanzado {

    use SesionTrait;

    public function getTodo(Request $request): Collection {
        return $this->modelo::select('id', 'usuario_id', 'empresa_id', 'rol_id')
            ->when($request->filled('con_relaciones') && filter_var($request->con_relaciones, FILTER_VALIDATE_BOOLEAN), function ($consulta) {
                $consulta->with(['usuario:id,...', 'rol:id,name']);
            })
            ->when($request->filled('validar_relaciones') && filter_var($request->validar_relaciones, FILTER_VALIDATE_BOOLEAN), function ($consulta) {
                $consulta->with(['usuario' => function ($consulta) {
                    $consulta->withExists('agendas as tiene_agendas');
                    $consulta->withExists('ofertasLaborales as tiene_ofertas_laborales');
                    $consulta->withExists('procesos as tiene_procesos');
                }]);
            })
            ->when($request->filled('nombres'), function ($consulta) use ($request) {
                $consulta->whereHas('usuario', function ($consulta) use ($request) {
                    $consulta->where('nombres', 'like', '%' . $request->nombre . '%');
                });
            })
            ->get();
    }

    public function getUnoAvanzado(Request $request): ?EmpresaUsuario {
        return $this->modelo::select('id', 'usuario_id', 'empresa_id', 'rol_id', 'email')
            ->when($request->filled('usuario_id'), fn($consulta) => $consulta->where('usuario_id', $request->usuario_id))
            ->when($request->filled('empresa_id'), fn($consulta) => $consulta->where('empresa_id', $request->empresa_id))
            ->when($request->filled('rol_id'), fn($consulta) => $consulta->where('rol_id', $request->rol_id))
            ->first();
    }

    public function actualizarUnoAvanzado(Request $request, array $datos): bool {
        return (bool) $this->modelo::when($request->filled('usuario_id'), fn($consulta) => $consulta->where('usuario_id', $request->usuario_id))
            ->when($request->filled('empresa_id'), fn($consulta) => $consulta->where('empresa_id', $request->empresa_id))
            ->when($request->filled('rol_id'), fn($consulta) => $consulta->where('rol_id', $request->rol_id))
            ->update($datos);
    }

    public function obtenerEmpresaActualUsuario(?int $usuario_id = null): ?Empresa {
        $usuario_id = is_null($usuario_id) ? Auth::id() : $usuario_id;
        $empresa_usuario = $this->modelo::where([
            ['usuario_id', '=', $usuario_id],
            ['empresa_id', '=', $this->obtenerDeSesion('empresa_id')],
            ['rol_id', '=', $this->obtenerDeSesion('rol_id')]
        ])->first();
        // ... retorna empresa con relaciones
    }
}
