                    $consulta->withExists('ofertasLaborales as tiene_ofertas_laborales');
                    $consulta->withExists('procesos as tiene_procesos');
                }]);
            })
            ->when($request->filled('nombres'), function ($consulta) use ($request) {
                $consulta->whereHas('usuario', function ($consulta) use ($request) {
                    $consulta->where('nombres', 'like', '%' . $request->nombre . '%');
                });
            })
            ->get();
    }

    public function getUnoAvanzado(Request $request): ?EmpresaUsuario {
        return $this->modelo::select('id', 'usuario_id', 'empresa_id', 'rol_id', 'email')
