   648→                'notificacion_id'          => $resultado_envio['notificacion_id'] ?? null,
   649→                'error'                    => $resultado_envio['error'] ?? null
   650→            ];
   651→        } catch (Exception $e) {
   652→            return [
   653→                'exito'                    => false,
   654→                'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
