   186→    /**
   187→     * Enviar mensaje de plantilla.
   188→     *
   189→     * @param int $plantilla_id ID de la plantilla.
   190→     * @param string $telefono Número de teléfono del destinatario (con código de país).
   191→     * @param array $variables Valores de las variables de la plantilla.
   192→     * @param int|null $linea_id ID de la línea de WhatsApp (opcional).
   193→     * @param array $parametros_encabezado Parámetros del header (opcional).
   194→     * @param array $parametros_botones Parámetros de botones (opcional).
   195→     * @param array $contexto Datos adicionales para el registro (usuario_id, modelo, modelo_id, tipo, etc.).
   196→     * @return array Resultado con 'exito', 'mensaje_id', 'notificacion_id' y datos adicionales.
   197→     * @author Esperanza Olivo
   198→     */
   199→    public function enviarMensajePlantilla(
   200→        int $plantilla_id,
   201→        string $telefono,
   202→        array $variables = [],
   203→        ?int $linea_id = null,
   204→        array $parametros_encabezado = [],
   205→        array $parametros_botones = [],
   206→        array $contexto = []
   207→    ): array {
   208→        if (!$this->estaConfigurado()) {
   209→            throw new Exception('La configuración de WhatsApp no está completa.');
   210→        }
   211→
   212→        $telefono_limpio = $this->limpiarNumeroTelefono($telefono);
   213→
   214→        $plantilla_nombre = null;
   215→        try {
   216→            $plantilla = $this->obtenerPlantilla($plantilla_id);
   217→            $plantilla_nombre = $plantilla['name'] ?? null;
   218→        } catch (Exception $e) {
   219→        }
   220→
   221→        $notificacion = $this->notificacion_repositorio->crear([
   222→            'vacante_id'              => $contexto['vacante_id'] ?? null,
   223→            'etapa_vacante_usuario_id'=> $contexto['etapa_vacante_usuario_id'] ?? null,
   224→            'telefono'                => $telefono_limpio,
   225→            'enviado_por'             => Auth::id(),
   226→            'plantilla_id'            => $plantilla_id,
   227→            'plantilla_nombre'        => $plantilla_nombre,
   228→            'variables'               => $variables,
   229→            'estado'                  => NotificacionWhatsApp::ESTADO_PENDIENTE,
   230→            'tipo'                    => $contexto['tipo'] ?? NotificacionWhatsApp::TIPO_GENERAL,
   231→            'metadata'                => $contexto['metadata'] ?? null
   232→        ]);
   233→
   234→        $payload = [
   235→            'apiKey'         => $this->api_key,
   236→            'templateId'     => $plantilla_id,
   237→            'lineId'         => $linea_id ?? $this->linea_id,
   238→            'to'             => $telefono_limpio,
   239→            'variableValues' => $variables,
   240→            'headerParams'   => $parametros_encabezado,
   241→            'buttonParams'   => $parametros_botones
   242→        ];
   243→
   244→        try {
   245→            $respuesta = $this->cliente->post($this->api_url . '/messages/send-template', [
   246→                'json' => $payload
   247→            ]);
   248→
   249→            $datos = json_decode($respuesta->getBody()->getContents(), true);
   250→
   251→            if (!$datos['success']) {
   252→                $mensaje_error = $datos['message'] ?? 'Error al enviar mensaje';
   253→                $notificacion->marcarComoFallido($mensaje_error);
   254→                throw new Exception($mensaje_error);
   255→            }
   256→
   257→            $mensaje_id = $datos['data']['messageId'] ?? null;
   258→            $notificacion->marcarComoEnviado($mensaje_id);
   259→
   260→            return [
   261→                'exito'           => true,
   262→                'mensaje_id'      => $mensaje_id,
   263→                'notificacion_id' => $notificacion->id,
   264→                'data'            => $datos['data'] ?? []
   265→            ];
   266→        } catch (RequestException $error) {
   267→            $mensaje_error = $this->extraerMensajeError($error);
   268→            $notificacion->marcarComoFallido($mensaje_error, (string) $error->getCode());
   269→            $this->manejarError($error, 'enviar mensaje');
   270→        }
   271→
   272→        return [
   273→            'exito'           => false,
   274→            'notificacion_id' => $notificacion->id,
   275→            'error'           => 'Error desconocido'
   276→        ];
   277→    }
