   279→    /**
   280→     * Extraer mensaje de error de una excepción de request.
   281→     *
   282→     * @param RequestException $error Excepción de la petición.
   283→     * @return string Mensaje de error.
   284→     * @author Esperanza Olivo
   285→     */
   286→    protected function extraerMensajeError(RequestException $error): string
   287→    {
   288→        if ($error->hasResponse()) {
   289→            $respuesta_error = json_decode($error->getResponse()->getBody()->getContents(), true);
   290→            return $respuesta_error['message'] ?? $respuesta_error['error'] ?? $error->getMessage();
   291→        }
   292→
   293→        return $error->getMessage();
   294→    }
