   296→    /**
   297→     * Limpiar y formatear número de teléfono.
   298→     *
   299→     * @param string $telefono Número de teléfono.
   300→     * @return string Número formateado.
   301→     * @author Esperanza Olivo
   302→     */
   303→    protected function limpiarNumeroTelefono(string $telefono): string
   304→    {
   305→        $telefono = preg_replace('/[\s\-\(\)\+]/', '', $telefono);
   306→
   307→        if (!str_starts_with($telefono, '57') && strlen($telefono) === 10) {
   308→            $telefono = '57' . $telefono;
   309→        }
   310→
   311→        return $telefono;
   312→    }
