   314→    /**
   315→     * Manejar errores de la API.
   316→     *
   317→     * @param RequestException $error Excepción de la petición.
   318→     * @param string $operacion Descripción de la operación.
   319→     * @throws Exception
   320→     * @author Esperanza Olivo
   321→     */
   322→    protected function manejarError(RequestException $error, string $operacion): void
   323→    {
   324→        $mensaje_error = "Error al {$operacion}";
   325→
   326→        if ($error->hasResponse()) {
   327→            $respuesta_error = json_decode($error->getResponse()->getBody()->getContents(), true);
   328→            $mensaje_error   = $respuesta_error['message'] ?? $respuesta_error['error'] ?? $mensaje_error;
   329→        }
   330→
   331→        throw new Exception($mensaje_error);
   332→    }
