    94→     * @author Esperanza Olivo
    95→     */
    96→    public function obtenerPlantillas(array $filtros = []): array
    97→    {
    98→        if (!$this->estaConfigurado()) {
    99→            throw new Exception('La configuración de WhatsApp no está completa.');
   100→        }
   101→
   102→        $parametros = array_merge(['apiKey' => $this->api_key], $filtros);
   103→
   104→        if (!isset($parametros['lineId']) && $this->linea_id) {
   105→            $parametros['lineId'] = $this->linea_id;
   106→        }
   107→
   108→        try {
   109→            $respuesta = $this->cliente->get($this->api_url . '/templates', [
   110→                'query' => $parametros
   111→            ]);
   112→
   113→            $datos = json_decode($respuesta->getBody()->getContents(), true);
   114→
   115→            if (!$datos['success']) {
   116→                throw new Exception($datos['message'] ?? 'Error al obtener plantillas');
   117→            }
   118→
   119→            return $datos['data'] ?? [];
   120→        } catch (RequestException $error) {
   121→            $this->manejarError($error, 'obtener plantillas');
