   147→
   148→    /**
   149→     * Obtener una plantilla por su ID.
   150→     *
   151→     * @param int $id ID de la plantilla.
   152→     * @return array|null
   153→     * @author Esperanza Olivo
   154→     */
   155→    public function obtenerPlantilla(int $id): ?array
   156→    {
