   177→    /**
   178→     * Enviar mensaje de plantilla.
   179→     *
   180→     * @param int $plantilla_id ID de la plantilla.
   181→     * @param string $telefono Número de teléfono del destinatario (con código de país).
   182→     * @param array $variables Valores de las variables de la plantilla.
   183→     * @param int|null $linea_id ID de la línea de WhatsApp (opcional).
   184→     * @param array $parametros_encabezado Parámetros del header (opcional).
   185→     * @param array $parametros_botones Parámetros de botones (opcional).
   186→     * @param array $contexto Datos adicionales para el registro (usuario_id, modelo, modelo_id, tipo, etc.).
   187→     * @return array Resultado con 'exito', 'mensaje_id', 'notificacion_id' y datos adicionales.
   188→     * @author Esperanza Olivo
   189→     */
   190→    public function enviarMensajePlantilla(
   191→        int $plantilla_id,
   192→        string $telefono,
   193→        array $variables = [],
   194→        ?int $linea_id = null,
   195→        array $parametros_encabezado = [],
   196→        array $parametros_botones = [],
   197→        array $contexto = []
   198→    ): array {
   199→        if (!$this->estaConfigurado()) {
   200→            throw new Exception('La configuración de WhatsApp no está completa.');
   201→        }
   202→
   203→        $telefono_limpio = $this->limpiarNumeroTelefono($telefono);
   204→
   205→        $plantilla_nombre = null;
   206→       
   207→        $plantilla = $this->obtenerPlantilla($plantilla_id);
   208→        $plantilla_nombre = $plantilla['name'] ?? null;
   209→
   210→        $notificacion = $this->notificacion_repositorio->crear([
   211→            'vacante_id'              => $contexto['vacante_id'] ?? null,
   212→            'etapa_vacante_usuario_id'=> $contexto['etapa_vacante_usuario_id'] ?? null,
   213→            'telefono'                => $telefono_limpio,
   214→            'enviado_por'             => Auth::id(),
   215→            'plantilla_id'            => $plantilla_id,
   216→            'plantilla_nombre'        => $plantilla_nombre,
   217→            'variables'               => $variables,
   218→            'estado_notificacion_whatsapp_id'                  => EstadoNotificacionWhatsApp::PENDIENTE_ID,
   219→            'tipo'                    => $contexto['tipo'] ?? NotificacionWhatsApp::TIPO_GENERAL,
   220→            'metadata'                => $contexto['metadata'] ?? null
   221→        ]);
   222→
   223→        $payload = [
   224→            'apiKey'         => $this->api_key,
   225→            'templateId'     => $plantilla_id,
   226→            'lineId'         => $linea_id ?? $this->linea_id,
   227→            'to'             => $telefono_limpio,
   228→            'variableValues' => $variables,
   229→            'headerParams'   => $parametros_encabezado,
   230→            'buttonParams'   => $parametros_botones
   231→        ];
   232→
   233→        try {
   234→            $respuesta = $this->cliente->post($this->api_url . '/messages/send-template', [
   235→                'json' => $payload
   236→            ]);
   237→
   238→            $datos = json_decode($respuesta->getBody()->getContents(), true);
   239→
   240→            if (!$datos['success']) {
   241→                $mensaje_error = $datos['message'] ?? 'Error al enviar mensaje';
   242→                $notificacion->marcarComoFallido($mensaje_error);
   243→                throw new Exception($mensaje_error);
   244→            }
   245→
   246→            $mensaje_id = $datos['data']['messageId'] ?? null;
   247→            $this->notificacion_repositorio->marcarComoEnviado($mensaje_id);
   248→
   249→            return [
   250→                'exito'           => true,
   251→                'mensaje_id'      => $mensaje_id,
   252→                'notificacion_id' => $notificacion->id,
   253→                'data'            => $datos['data'] ?? []
   254→            ];
   255→        } catch (RequestException $error) {
   256→            $mensaje_error = $this->extraerMensajeError($error);
   257→            $notificacion->marcarComoFallido($mensaje_error, (string) $error->getCode());
   258→            $this->manejarError($error, 'enviar mensaje');
   259→        }
   260→
   261→        return [
   262→            'exito'           => false,
   263→            'notificacion_id' => $notificacion->id,
   264→            'error'           => 'Error desconocido'
   265→        ];
   266→    }
