   335→            'notificaciones_enviadas'   => 0,
   336→            'notificaciones_fallidas'   => 0,
   337→            'canal_comunicacion'        => 'whatsapp',
   338→            'detalles_notificaciones'   => []
   339→        ];
   340→
   341→        foreach ($candidatos as $candidato) {
   342→            
   343→            $etapa_vacante_usuario_id = $candidato['etapa_vacante_usuario_id'];
   344→            $usuario_vacante = $this->etapa_vacante_usuario_repositorio->getUno($etapa_vacante_usuario_id);
