   187→    public function enviarMensajePlantilla(
   188→        int $plantilla_id,
   189→        string $telefono,
   190→        array $variables = [],
   191→        ?int $linea_id = null,
   192→        array $parametros_encabezado = [],
   193→        array $parametros_botones = [],
   194→        array $contexto = []
   195→    ): array {
   196→        if (!$this->estaConfigurado()) {
   197→            throw new Exception('La configuración de WhatsApp no está completa.');
   198→        }
   199→
   200→        $telefono_limpio = $this->limpiarNumeroTelefono($telefono);
   201→
   202→        $plantilla_nombre = null;
   203→
   204→        $plantilla        = $this->obtenerPlantilla($plantilla_id);
   205→        $plantilla_nombre = $plantilla['name'] ?? null;
   206→
   207→        $notificacion = $this->notificacion_repositorio->crear([
   208→            'etapa_vacante_usuario_id'        => $contexto['etapa_vacante_usuario_id'] ?? null,
   209→            'telefono'                        => $telefono_limpio,
   210→            'enviado_por'                     => Auth::id(),
   211→            'plantilla_id'                    => $plantilla_id,
   212→            'plantilla_nombre'                => $plantilla_nombre,
   213→            'variables'                       => $variables,
   214→            'estado_notificacion_whatsapp_id' => EstadoNotificacionWhatsApp::PENDIENTE_ID,
   215→            'tipo'                            => $contexto['tipo'] ?? NotificacionWhatsApp::TIPO_GENERAL,
   216→            'metadata'                        => $contexto['metadata'] ?? null
   217→        ]);
   218→
   219→        $payload = [
   220→            'apiKey'         => $this->api_key,
   221→            'templateId'     => $plantilla_id,
   222→            'lineId'         => $linea_id ?? $this->linea_id,
   223→            'to'             => $telefono_limpio,
   224→            'variableValues' => $variables,
   225→            'headerParams'   => $parametros_encabezado,
   226→            'buttonParams'   => $parametros_botones
   227→        ];
   228→
   229→        try {
   230→            $respuesta = $this->cliente->post($this->api_url . '/messages/send-template', [
   231→                'json' => $payload
   232→            ]);
   233→
   234→            $datos = json_decode($respuesta->getBody()->getContents(), true);
   235→
   236→            if (!$datos['success']) {
   237→                $mensaje_error = $datos['message'] ?? 'Error al enviar mensaje';
   238→                $notificacion->marcarComoFallido($mensaje_error);
   239→                throw new Exception($mensaje_error);
   240→            }
   241→
   242→            $mensaje_id = $datos['data']['messageId'] ?? null;
   243→            $this->notificacion_repositorio->marcarComoEnviado($mensaje_id);
   244→
   245→            return [
   246→                'exito'           => true,
   247→                'mensaje_id'      => $mensaje_id,
   248→                'notificacion_id' => $notificacion->id,
   249→                'data'            => $datos['data'] ?? []
   250→            ];
   251→        } catch (RequestException $error) {
   252→            $mensaje_error = $this->extraerMensajeError($error);
   253→            $notificacion->marcarComoFallido($mensaje_error, (string) $error->getCode());
   254→            $this->manejarError($error, 'enviar mensaje');
   255→        }
   256→
   257→        return [
   258→            'exito'           => false,
   259→            'notificacion_id' => $notificacion->id,
   260→            'error'           => 'Error desconocido'
   261→        ];
   262→    }
