   260→            'error'           => 'Error desconocido'
   261→        ];
   262→    }
   263→
   264→    /**
   265→     * Extraer mensaje de error de una excepción de request.
   266→     *
   267→     * @param RequestException $error Excepción de la petición.
   268→     * @return string Mensaje de error.
   269→     * @author Esperanza Olivo
   270→     */
   271→    protected function extraerMensajeError(RequestException $error): string {
   272→        if ($error->hasResponse()) {
   273→            $respuesta_error = json_decode($error->getResponse()->getBody()->getContents(), true);
   274→            return $respuesta_error['message'] ?? $respuesta_error['error'] ?? $error->getMessage();
   275→        }
   276→
   277→        return $error->getMessage();
   278→    }
