   285→     * @throws Exception
   286→     * @author Esperanza Olivo
   287→     */
   288→    protected function manejarError(RequestException $error, string $operacion): void {
   289→        $mensaje_error = "Error al {$operacion}";
   290→
   291→        if ($error->hasResponse()) {
   292→            $respuesta_error = json_decode($error->getResponse()->getBody()->getContents(), true);
   293→            $mensaje_error   = $respuesta_error['message'] ?? $respuesta_error['error'] ?? $mensaje_error;
   294→        }
   295→
   296→        throw new Exception($mensaje_error);
   297→    }
