   299→    /**
   300→     * Reenviar notificaciones de WhatsApp fallidas.
   301→     *
   302→     * @param int $vacante_id ID de la vacante.
   303→     * @param array $candidatos Lista de candidatos a reenviar.
   304→     * @return array Resultado con estadísticas de envío.
   305→     * @author Esperanza Olivo
   306→     */
   307→    public function reenviarNotificaciones(int $vacante_id, array $candidatos): array {
   308→        $vacante = $this->vacante_repositorio->getUno($vacante_id);
   309→        $empresa = $vacante->empresa;
   310→
   311→        $plantilla_id = $this->obtenerIdPlantillaPorNombre('invitacion_etapa_1');
   312→
   313→        if (!$plantilla_id) {
   314→            return [
   315→                'total_candidatos'        => count($candidatos),
   316→                'candidatos_procesados'   => 0,
   317→                'notificaciones_enviadas' => 0,
   318→                'notificaciones_fallidas' => count($candidatos),
   319→                'canal_comunicacion'      => 'whatsapp',
   320→                'error'                   => 'No se encontró la plantilla de WhatsApp "invitacion_etapa_1"',
   321→                'detalles_notificaciones' => []
   322→            ];
   323→        }
   324→
   325→        $resultado = [
   326→            'total_candidatos'        => count($candidatos),
   327→            'candidatos_procesados'   => 0,
   328→            'notificaciones_enviadas' => 0,
   329→            'notificaciones_fallidas' => 0,
   330→            'canal_comunicacion'      => 'whatsapp',
   331→            'detalles_notificaciones' => []
   332→        ];
   333→
   334→        foreach ($candidatos as $candidato) {
   335→            $etapa_vacante_usuario_id = $candidato['etapa_vacante_usuario_id'];
   336→            $usuario_vacante          = $this->etapa_vacante_usuario_repositorio->getUno($etapa_vacante_usuario_id);
   337→            $etapa                    = $vacante->etapas()->where('activa', true)->orderBy('orden')->first();
   338→            $plantilla_nombre         = $this->resolverNombrePlantilla($etapa->nombre);
   339→            $plantilla_id             = $this->obtenerIdPlantillaPorNombre($plantilla_nombre);
   340→
   341→            $usuario          = $usuario_vacante->usuario;
   342→            $nombre_candidato = trim($usuario->nombres . ' ' . $usuario->apellidos) ?: 'Candidato';
   343→            $telefono         = $candidato['telefono'] ?? $usuario->telefono;
   344→
   345→            if (!$plantilla_id) {
   346→                $resultado['notificaciones_fallidas']++;
   347→                $resultado['detalles_notificaciones'][] = [
   348→                    'exito'                    => false,
   349→                    'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   350→                    'nombre'                   => $nombre_candidato,
   351→                    'error'                    => "No se encontró la plantilla '{$plantilla_nombre}'"
   352→                ];
   353→                continue;
   354→            }
   355→
   356→            $usuario          = $usuario_vacante->usuario;
   357→            $nombre_candidato = trim($usuario->nombres . ' ' . $usuario->apellidos) ?: 'Candidato';
   358→            $telefono         = $candidato['telefono'] ?? $usuario->telefono;
   359→
   360→            if (empty($telefono)) {
   361→                $resultado['notificaciones_fallidas']++;
   362→                $resultado['detalles_notificaciones'][] = [
   363→                    'exito'                    => false,
   364→                    'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   365→                    'usuario_id'               => $usuario->id,
   366→                    'nombre'                   => $nombre_candidato,
   367→                    'telefono'                 => null,
   368→                    'error'                    => 'El candidato no tiene número de teléfono'
   369→                ];
   370→                continue;
   371→            }
   372→
   373→            $token_acceso = $this->token_servicio->generar($usuario->id);
   374→            $enlace       = request()->getSchemeAndHttpHost() . "/control-acceso/{$token_acceso->token}?vacante_id={$vacante->id}";
   375→            $variables    = $this->construirVariablesPlantilla(
   376→                $etapa->nombre,
   377→                $nombre_candidato,
   378→                $empresa->nombre_comercial ?? $empresa->razon_social ?? 'La empresa',
   379→                $vacante->nombre_vacante ?? 'la vacante',
   380→                $enlace
   381→            );
   382→
   383→            try {
   384→                $resultado_envio = $this->enviarMensajePlantilla(
   385→                    $plantilla_id,
   386→                    $telefono,
   387→                    $variables,
   388→                    null,
   389→                    [],
   390→                    [],
   391→                    [
   392→                        'etapa_vacante_usuario_id' => $usuario_vacante?->id,
   393→                        'tipo'                     => 'reintento',
   394→                        'metadata'                 => [
   395→                            'etapa_id'     => $etapa->id ?? null,
   396→                            'etapa_nombre' => $etapa->nombre ?? null,
   397→                            'empresa_id'   => $empresa->id
   398→                        ]
   399→                    ]
   400→                );
   401→
   402→                $resultado['candidatos_procesados']++;
   403→
   404→                if ($resultado_envio['exito'] ?? false) {
   405→                    $resultado['notificaciones_enviadas']++;
   406→                    $resultado['detalles_notificaciones'][] = [
   407→                        'exito'                    => true,
   408→                        'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   409→                        'usuario_id'               => $usuario->id,
   410→                        'nombre'                   => $nombre_candidato,
   411→                        'telefono'                 => $telefono,
   412→                        'mensaje_id'               => $resultado_envio['mensaje_id'] ?? null,
   413→                        'notificacion_id'          => $resultado_envio['notificacion_id'] ?? null
   414→                    ];
   415→                } else {
   416→                    $resultado['notificaciones_fallidas']++;
   417→                    $resultado['detalles_notificaciones'][] = [
   418→                        'exito'                    => false,
   419→                        'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   420→                        'usuario_id'               => $usuario->id,
   421→                        'nombre'                   => $nombre_candidato,
   422→                        'telefono'                 => $telefono,
   423→                        'error'                    => $resultado_envio['error'] ?? 'Error al enviar'
   424→                    ];
   425→                }
   426→            } catch (Exception $error) {
   427→                $resultado['notificaciones_fallidas']++;
   428→                $resultado['detalles_notificaciones'][] = [
   429→                    'exito'                    => false,
   430→                    'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   431→                    'usuario_id'               => $usuario->id,
   432→                    'nombre'                   => $nombre_candidato,
   433→                    'telefono'                 => $telefono,
   434→                    'error'                    => $error->getMessage()
   435→                ];
   436→            }
   437→        }
   438→
   439→        return $resultado;
   440→    }
   441→
   442→    /**
   443→     * Obtener notificaciones fallidas o pendientes de una vacante agrupadas por usuario.
   444→     *
   445→     * @param int $vacante_id ID de la vacante.
   446→     * @return array Lista de usuarios con notificaciones fallidas o pendientes.
   447→     * @author Esperanza Olivo
   448→     */
   449→    public function obtenerNotificacionesFallidas(int $vacante_id): array {
   450→        $notificaciones = $this->notificacion_repositorio->obtenerFallidasPorVacante($vacante_id);
   451→        $resultado      = [];
   452→
   453→        foreach ($notificaciones as $etapa_vacante_usuario_id => $notifificaciones_usuario) {
   454→            $ultima  = $notifificaciones_usuario->first();
   455→            $usuario = $ultima->etapaVacanteUsuario?->usuario;
   456→
   457→            $resultado[] = [
   458→                'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   459→                'nombre'                   => $usuario ? trim($usuario->nombres . ' ' . $usuario->apellidos) : 'Desconocido',
   460→                'telefono'                 => $ultima->telefono,
   461→                'ultimo_error'             => $ultima->error_mensaje,
   462→                'ultimo_intento'           => $ultima->created_at->format('d/m/Y H:i'),
   463→                'intentos'                 => $notifificaciones_usuario->count(),
   464→                'notificacion_id'          => $ultima->id
   465→            ];
   466→        }
   467→
   468→        return $resultado;
   469→    }
