   471→    /**
   472→     * Reenviar notificación individual a un candidato.
   473→     *
   474→     * @param int $vacante_id ID de la vacante.
   475→     * @param int $etapa_vacante_usuario_id ID del usuario en la vacante.
   476→     * @param string $telefono Teléfono del usuario.
   477→     * @return array Resultado del envío.
   478→     * @author Esperanza Olivo
   479→     */
   480→    public function reenviarNotificacionIndividual(int $vacante_id, int $etapa_vacante_usuario_id, string $telefono): array {
   481→        $vacante         = $this->vacante_repositorio->getUno($vacante_id);
   482→        $usuario_vacante = $this->etapa_vacante_usuario_repositorio->getUno($etapa_vacante_usuario_id);
   483→
   484→        if (!$vacante || !$usuario_vacante || !$usuario_vacante->usuario) {
   485→            return [
   486→                'exito' => false,
   487→                'error' => 'Vacante o candidato no encontrado'
   488→            ];
   489→        }
   490→
   491→        $usuario = $usuario_vacante->usuario;
   492→        $empresa = $vacante->empresa;
   493→
   494→        $etapa = $usuario_vacante->etapa;
   495→
   496→        $plantilla_nombre = $this->resolverNombrePlantilla($etapa->nombre);
   497→
   498→        $plantilla_whatsapp_id = $this->obtenerIdPlantillaPorNombre($plantilla_nombre);
   499→
   500→        if (!$plantilla_whatsapp_id) {
   501→            return [
   502→                'exito' => false,
   503→                'error' => "No se encontró la plantilla de WhatsApp '{$plantilla_nombre}'"
   504→            ];
   505→        }
   506→
   507→        $nombre_candidato = trim($usuario->nombres . ' ' . $usuario->apellidos) ?: 'Candidato';
   508→        $token_acceso     = $this->token_servicio->generar($usuario->id);
   509→        $enlace           = request()->getSchemeAndHttpHost() . "/control-acceso/{$token_acceso->token}?vacante_id={$vacante->id}";
   510→
   511→        $nombre_empresa = $empresa->nombre_comercial ?? $empresa->razon_social ?? 'La empresa';
   512→        $nombre_vacante = $vacante->nombre_vacante ?? 'la vacante';
   513→
   514→        $variables = $this->construirVariablesPlantilla(
   515→            $etapa->nombre,
   516→            $nombre_candidato,
   517→            $nombre_empresa,
   518→            $nombre_vacante,
   519→            $enlace
   520→        );
   521→
   522→        try {
   523→            $resultado_envio = $this->enviarMensajePlantilla(
   524→                $plantilla_whatsapp_id,
   525→                $telefono,
   526→                $variables,
   527→                null,
   528→                [],
   529→                [],
   530→                [
   531→                    'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   532→                    'tipo'                     => 'reintento_individual',
   533→                    'metadata'                 => [
   534→                        'etapa_id'     => $etapa->id ?? null,
   535→                        'etapa_nombre' => $etapa->nombre ?? null,
   536→                        'empresa_id'   => $empresa->id ?? null
   537→                    ]
   538→                ]
   539→            );
   540→
   541→            if ($resultado_envio['exito'] ?? false) {
   542→                $this->notificacion_repositorio->actualizarEstadosPrevios(
   543→                    $etapa_vacante_usuario_id,
   544→                    $resultado_envio['notificacion_id'] ?? 0
   545→                );
   546→            }
   547→
   548→            return [
   549→                'exito'                    => $resultado_envio['exito'] ?? false,
   550→                'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   551→                'nombre'                   => $nombre_candidato,
   552→                'telefono'                 => $telefono,
   553→                'mensaje_id'               => $resultado_envio['mensaje_id'] ?? null,
   554→                'notificacion_id'          => $resultado_envio['notificacion_id'] ?? null,
   555→                'error'                    => $resultado_envio['error'] ?? null
   556→            ];
   557→        } catch (Exception $error) {
   558→            return [
   559→                'exito'                    => false,
   560→                'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   561→                'nombre'                   => $nombre_candidato,
   562→                'telefono'                 => $telefono,
   563→                'error'                    => $error->getMessage()
   564→            ];
   565→        }
   566→    }
   567→
   568→    /**
   569→     * Parsear el nombre de la plantilla según la etapa.
   570→     *
   571→     * @param string $nombre_etapa Nombre de la etapa.
   572→     * @return string Nombre de la plantilla.
   573→     * @author Esperanza Olivo
   574→     */
   575→    private function resolverNombrePlantilla(string $nombre_etapa): string {
   576→        return match ($nombre_etapa) {
   577→            EtapaVacante::CONTRATADOS_NOMBRE, 'Contratados' => 'notificacion_contratado',
   578→            EtapaVacante::DESCARTADOS_NOMBRE, 'Descartados' => 'descartado',
   579→            default => 'invitacion_etapa_1'
   580→        };
   581→    }
   582→
   583→    /**
   584→     * Construir las variables de la plantilla según la etapa.
   585→     *
   586→     * @param string $nombre_etapa Nombre de la etapa.
   587→     * @param string $nombre_candidato Nombre del candidato.
   588→     * @param string $nombre_empresa Nombre de la empresa.
   589→     * @param string $nombre_vacante Nombre de la vacante.
   590→     * @param string $enlace Enlace de acceso.
   591→     * @return array Variables para la plantilla.
   592→     * @author Esperanza Olivo
   593→     */
   594→    private function construirVariablesPlantilla(
   595→        string $nombre_etapa,
   596→        string $nombre_candidato,
   597→        string $nombre_empresa,
   598→        string $nombre_vacante,
   599→        string $enlace
   600→    ): array {
   601→        return match ($nombre_etapa) {
   602→            EtapaVacante::CONTRATADOS_NOMBRE, 'Contratados' => [
   603→                $nombre_candidato,
   604→                $nombre_empresa,
   605→                $nombre_vacante
   606→            ],
   607→            EtapaVacante::DESCARTADOS_NOMBRE, 'Descartados' => [],
   608→            default => [
   609→                $nombre_candidato,
   610→                $nombre_empresa,
   611→                $nombre_vacante,
   612→                $nombre_etapa ?? 'la etapa',
   613→                Carbon::now()->addDays(7)->format('d/m/Y'),
   614→                $enlace
   615→            ]
   616→        };
   617→    }
   618→
   619→    /**
   620→     * Obtener plantillas de WhatsApp aprobadas.
   621→     *
   622→     * @param Request $request Contenido de la petición.
   623→     * @return JsonResponse
   624→     * @author Esperanza Olivo
   625→     */
   626→    public function plantillas(Request $request): JsonResponse {
   627→        try {
   628→            if (!$this->estaConfigurado()) {
   629→                return new JsonResponse([
   630→                    'message' => 'La integración de WhatsApp no está configurada.',
   631→                    'data'    => []
   632→                ], 400);
   633→            }
   634→
   635→            $linea_id   = $request->input('linea_id');
   636→            $plantillas = $this->obtenerPlantillasAprobadas($linea_id);
   637→
   638→            return new JsonResponse([
   639→                'message' => 'Plantillas obtenidas correctamente.',
   640→                'data'    => $plantillas->values()->toArray()
   641→            ], 200);
   642→        } catch (Exception $error) {
   643→            return new JsonResponse([
   644→                'message' => 'Error al obtener plantillas.',
   645→                'errors'  => $error->getMessage()
   646→            ], 500);
   647→        }
   648→    }
   649→
   650→    /**
   651→     * Obtener una plantilla específica.
   652→     *
   653→     * @param int $plantilla_id ID de la plantilla.
   654→     * @return JsonResponse
   655→     * @author Esperanza Olivo
   656→     */
   657→    public function plantilla(int $plantilla_id): JsonResponse {
   658→        try {
   659→            if (!$this->estaConfigurado()) {
   660→                return new JsonResponse([
   661→                    'message' => 'La integración de WhatsApp no está configurada.',
   662→                    'data'    => null
   663→                ], 400);
   664→            }
   665→
   666→            $plantilla = $this->obtenerPlantilla($plantilla_id);
   667→
   668→            if (!$plantilla) {
   669→                return new JsonResponse([
   670→                    'message' => 'Plantilla no encontrada.',
   671→                    'data'    => null
   672→                ], 404);
   673→            }
   674→
   675→            return new JsonResponse([
   676→                'message' => 'Plantilla obtenida correctamente.',
   677→                'data'    => $plantilla
   678→            ], 200);
   679→        } catch (Exception $error) {
   680→            return new JsonResponse([
   681→                'message' => 'Error al obtener la plantilla.',
   682→                'errors'  => $error->getMessage()
   683→            ], 500);
   684→        }
   685→    }
   686→
   687→    /**
   688→     * Obtener mensaje de estado para el resultado del envío de notificaciones.
   689→     *
   690→     * @param array $resultado Resultado del proceso de envío de notificaciones.
   691→     * @return string Mensaje de estado.
   692→     * @author Esperanza Olivo
   693→     */
   694→    public function obtenerMensajeEstado(array $resultado): string {
   695→        $canal    = $resultado['canal_comunicacion'] ?? 'correo';
   696→        $enviadas = $resultado['notificaciones_enviadas'] ?? 0;
   697→        $fallidas = $resultado['notificaciones_fallidas'] ?? 0;
   698→
   699→        if ($canal === 'whatsapp') {
   700→            if ($fallidas === 0) {
   701→                $respuesta['message'] = "Candidatos agregados exitosamente. Se enviaron {$enviadas} notificaciones por WhatsApp.";
   702→            } elseif ($enviadas > 0) {
   703→                $respuesta['message'] = "Candidatos agregados. WhatsApp: {$enviadas} enviados, {$fallidas} fallidos.";
   704→            } else {
   705→                $respuesta['message'] = "Candidatos agregados, pero fallaron todas las notificaciones de WhatsApp ({$fallidas}).";
   706→            }
   707→        } else {
   708→            $respuesta['message'] = "Candidatos agregados exitosamente. Se enviaron {$enviadas} correos.";
   709→        }
   710→        return $respuesta['message'];
   711→    }
   712→}
