    44→function obtenerConfigPlantillaWhatsApp(nombre_etapa) {
    45→    if (nombre_etapa === 'Contratados') {
    46→        return PLANTILLAS_WHATSAPP.CONTRATADOS;
    47→    }
    48→    if (nombre_etapa === 'Descartados') {
