    54→/**
    55→ * Buscar plantilla de WhatsApp por nombre o ID
    56→ *
    57→ * @param {Array} plantillas Lista de plantillas disponibles
    58→ * @param {Object} configuracion Configuración de la plantilla a buscar
    59→ * @returns {Object|null} Plantilla encontrada o null
    60→ * @autor Esperanza Olivo
    61→ */
    62→function buscarPlantillaWhatsApp(plantillas, configuracion) {
    63→    if (!plantillas || plantillas.length === 0) {
    64→        return null;
    65→    }
    66→
    67→    if (configuracion.id) {
    68→        let por_id = plantillas.find(plantilla => plantilla.id == configuracion.id);
    69→        if (por_id) return por_id;
    70→    }
    71→
    72→    if (configuracion.nombre) {
    73→        let por_nombre = plantillas.find(plantilla => plantilla.name === configuracion.nombre);
    74→        if (por_nombre) return por_nombre;
    75→    }
    76→
    77→    return null;
    78→}
