   130→ *
   131→ * @param {Array} plantillas Lista de plantillas
   132→ * @param {number|null} seleccionada ID de la plantilla seleccionada
   133→ * @returns {string} HTML del selector
   134→ * @author Esperanza Olivo
   135→ */
   136→function generarSelectorPlantillasWhatsApp(plantillas, seleccionada = null) {
   137→    if (!plantillas || plantillas.length === 0) {
   138→        return `
   139→            <div class="alert alert-warning" role="alert">
   140→                <i class="bi bi-exclamation-triangle me-2"></i>
   141→                No hay plantillas de WhatsApp disponibles. Configura plantillas aprobadas en tu cuenta de WhatsApp Business.
   142→            </div>
   143→        `;
   144→    }
   145→
   146→    let opciones = plantillas.map(plantilla => {
   147→        let seleccion = seleccionada && plantilla.id == seleccionada ? 'selected' : '';
   148→        return `<option value="${plantilla.id}" ${seleccion}>${plantilla.name}</option>`;
   149→    }).join('');
   150→
   151→    return `
   152→        <div class="row">
