   154→                <label class="form-label text-body-2">Selecciona una plantilla de WhatsApp</label>
   155→                <select class="form-select" id="plantilla_whatsapp_id" name="plantilla_whatsapp_id">
   156→                    <option value="">Seleccionar plantilla...</option>
   157→                    ${opciones}
   158→                </select>
