   187→                    <h6 class="card-subtitle mb-2 text-muted">
   188→                        <i class="bi bi-whatsapp text-success me-2"></i>Vista previa
   189→                    </h6>
   190→                    <div class="card-text whatsapp-preview">
   191→                        ${contenido}
   192→                    </div>
   193→                    <div class="mt-2">
   194→                        <small class="text-muted">
   195→                            <i class="bi bi-info-circle me-1"></i>
   196→                            Las variables serán reemplazadas con los datos del candidato.
   197→                        </small>
   198→                    </div>
   199→                </div>
   200→            </div>
   201→        `);
   202→    }
   203→}
   204→
   205→/**
   206→ * Inicializar eventos del selector de plantillas WhatsApp
   207→ *
   208→ * @return {void}
   209→ * @author Esperanza Olivo
   210→ */
   211→function inicializarEventosPlantillasWhatsApp() {
   212→    $(document).off('change', '#plantilla_whatsapp_id').on('change', '#plantilla_whatsapp_id', function() {
   213→        mostrarPreviewPlantillaWhatsApp($(this).val());
