   216→
   217→/**
   218→ * Obtener el canal de comunicación de la vacante actual
   219→ *
   220→ * @returns {string} Canal de comunicación ('correo' o 'whatsapp')
   221→ * @author Esperanza Olivo
   222→ */
   223→function obtenerCanalComunicacionVacante() {
   224→    if (typeof vacante_datos !== 'undefined' && vacante_datos.canal_comunicacion) {
   225→        return vacante_datos.canal_comunicacion;
   226→    }
   227→
   228→    if (typeof window.vacante_edicion !== 'undefined' && window.vacante_edicion.canal_comunicacion) {
   229→        return window.vacante_edicion.canal_comunicacion;
   230→    }
   231→
   232→    let canal_input = $('input[name="canal_comunicacion"]:checked');
   233→    if (canal_input.length) {
