public function getTodoAplicante(Request $request): Collection {
    return $this->modelo::select('id', 'vacante_id', 'nombre', 'orden', 'fija', 'editable', 'activa')
    ->with([
        'archivos:id,modelo,modelo_id,nombre,nombre_original_archivo,ruta',
        'usuariosVacantes' => function ($consulta) use ($request) {
            $consulta->select('id', 'usuario_id', 'etapa_vacante_id', 'puntaje', 'puntaje_ia', 'fecha_notificacion', 'activo', 'created_at')
            ->when($request->filled('ciudad_id'), function ($sub_consulta) use ($request) {
                $sub_consulta->whereHas('usuario', fn($usuario) => $usuario->where('ciudad_id', $request->ciudad_id));
            })
            ->when($request->filled('departamento_id'), function ($sub_consulta) use ($request) {
                $sub_consulta->whereHas('usuario.ciudad', fn($ciudad) => $ciudad->where('departamento_id', $request->departamento_id));
            })
            ->when($request->filled('pais_id'), function ($sub_consulta) use ($request) {
                $sub_consulta->whereHas('usuario.ciudad.departamento', fn($departamento) => $departamento->where('pais_id', $request->pais_id));
            })
            ->when($request->filled('nivel_educativo_id'), function ($sub_consulta) use ($request) {
                $sub_consulta->whereHas('usuario.perfilesLaborales.estudios', fn($estudios) => $estudios->where('nivel_educativo_id', $request->nivel_educativo_id));
            })
            ->when($request->filled('fecha_desde'), function ($sub_consulta) use ($request) {
                $sub_consulta->whereDate('created_at', '>=', $request->fecha_desde);
            })
            ->when($request->filled('fecha_hasta'), function ($sub_consulta) use ($request) {
                $sub_consulta->whereDate('created_at', '<=', $request->fecha_hasta);
            })
            ->when($request->filled('edad'), function ($sub_consulta) use ($request) {
                $sub_consulta->whereHas('usuario', function ($usuario) use ($request) {
                    $usuario->whereRaw('TIMESTAMPDIFF(YEAR, fecha_nacimiento, CURDATE()) = ?', [$request->edad]);
                });
            })
            ->when($request->filled('chips'), function ($sub_consulta) use ($request) {
                $sub_consulta->where(function ($consulta_chips) use ($request) {
                    foreach ($request->chips as $chip) {
                        $consulta_chips->orWhereHas('usuario', function ($usuario_consulta) use ($chip) {
                            $usuario_consulta->where(function ($consulta) use ($chip) {
                                $consulta->where('nombres', 'like', "%{$chip}%")
                                    ->orWhere('apellidos', 'like', "%{$chip}%")
                                    ->orWhere('documento', 'like', "%{$chip}%")
                                    ->orWhereRaw("CONCAT(nombres, ' ', apellidos) like ?", ["%{$chip}%"])
                                    ->orWhereHas('perfilesLaborales', function ($perfil_consulta) use ($chip) {
                                        $perfil_consulta->where('salario', 'like', "%{$chip}%")
                                            ->orWhere('salario_maximo', 'like', "%{$chip}%");
                                    });
                            });
                        });
                    }
                });
            })
            ->where('activo', true);
        },
        'usuariosVacantes.usuario:id,ciudad_id,nombres,apellidos,documento',
        'usuariosVacantes.usuario.ciudad:id,departamento_id,nombre',
        'usuariosVacantes.usuario.ciudad.departamento:id,pais_id,nombre',
        'usuariosVacantes.usuario.ciudad.departamento.pais:id,nombre',
        'usuariosVacantes.usuario.perfilesLaborales' => function ($consulta) {
            $consulta->select(
                'id',
                'usuario_id',
                'salario',
                'salario_maximo',
                DB::raw("(SELECT SUM(
                    TIMESTAMPDIFF(MONTH,
                        experiencias_laborales.fecha_inicio,
                        COALESCE(experiencias_laborales.fecha_fin, CURDATE())
                    )
                )
                FROM experiencias_laborales
                WHERE experiencias_laborales.modelo_id = perfiles_laborales.id
                AND experiencias_laborales.model_type = '" . addslashes(PerfilLaboral::class) . "'
                ) as experiencia_laboral_meses")
            );
        }
    ])
    ->when($request->filled('vacante_id'), fn($consulta) => $consulta->where('vacante_id', $request->vacante_id))
    ->when($request->filled('etapa_id'), fn($consulta) => $consulta->where('id', $request->etapa_id))
    ->when(
        $request->filled('descartados'),
        fn($consulta) => $consulta->where('nombre', EtapaVacante::DESCARTADOS_NOMBRE),
        fn($consulta) => $consulta->where('nombre', '!=', EtapaVacante::DESCARTADOS_NOMBRE)
    )
