function reintentarNotificacionWhatsAppIndividual(etapa_vacante_usuario_id, telefono, nombre) {
    Swal.fire({
        title: 'Reintentar notificación',
        text: `¿Deseas reenviar la notificación de WhatsApp a ${nombre}?`,
        icon: 'question',
        showCancelButton: true,
        confirmButtonText: 'Sí, reenviar',
        cancelButtonText: 'Cancelar',
        showLoaderOnConfirm: true,
        preConfirm: () => {
            return $.ajax({
                url: '/whatsapp/reenviar-individual',
                type: 'POST',
                dataType: 'json',
                contentType: 'application/json',
                data: JSON.stringify({
                    vacante_id: VACANTE_ID,
                    etapa_vacante_usuario_id: etapa_vacante_usuario_id,
                    telefono: telefono
                })
            }).then(function(respuesta) {
                return respuesta;
            }).catch(function(error) {
                Swal.showValidationMessage('Error al reenviar: ' + (error.responseJSON?.mensaje || 'Error desconocido'));
            });
        },
        allowOutsideClick: () => !Swal.isLoading()
    }).then((resultado) => {
        if (resultado.isConfirmed && resultado.value) {
            if (resultado.value.exito) {
                delete notificaciones_fallidas_whatsapp[etapa_vacante_usuario_id];
                mostrarToast('success', `Notificación enviada exitosamente a ${nombre}`);
                // Recargar notificaciones fallidas y luego las etapas
                cargarNotificacionesFallidasWhatsApp(function() {
                    cargarEtapasConCandidatos(json_filtros_etapas);
                });
            } else {
                mostrarToast('danger', `Error al enviar a ${nombre}: ${resultado.value.error || 'Error desconocido'}`);
            }
        }
    });
}

